    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Туш для вій Essence Lash Princess — популярний вибір для створення ефекту об''єму та неймовірної довжини. Стійка формула, що не тестується на тваринах, забезпечує виразний та ефектний погляд протягом усього дня.'::text)) WHERE id = 1;
