    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Свіжий та яскравий зелений болгарський перець, який додасть насиченого смаку та кольору вашим стравам.'::text)) WHERE id = 25;
