    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Свіже та поживне молоко — базовий продукт для приготування різноманітних страв та щоденного споживання.'::text)) WHERE id = 32;
