    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Чиста та освіжаюча бутильована вода, необхідна для підтримки водного балансу протягом дня.'::text)) WHERE id = 42;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Декоративні гойдалки стануть чарівним доповненням вашого інтер''єру. Завдяки витонченим деталям вони додадуть елегантності та нотки легкості будь-якій кімнаті.'::text)) WHERE id = 43;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Фоторамка «Родове дерево» — це стильний та сентиментальний спосіб зберегти цінні сімейні спогади. Кілька слотів для фото дозволять створити справжню історію вашої родини.'::text)) WHERE id = 44;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Штучна декоративна рослина допоможе додати природного затишку вашому дому без зайвого клопоту з догляду. Вона оживить будь-який простір, надаючи йому стильного вигляду.'::text)) WHERE id = 45;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Стильний горщик для ваших улюблених рослин. Завдяки лаконічному дизайну він ідеально впишеться в інтер''єр вашого дому чи саду, додаючи нотку сучасності.'::text)) WHERE id = 46;
