    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Бамбукова лопатка — універсальний кухонний інструмент з екологічного матеріалу. Ідеально підходить для перевертання, перемішування та подачі страв.'::text)) WHERE id = 48;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Чорна алюмінієва чашка — стильна та міцна ємність для гарячих і холодних напоїв. Елегантний дизайн додасть сучасності вашій колекції посуду.'::text)) WHERE id = 49;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Чорний вінчик — незамінний інструмент на кухні для збивання інгредієнтів. Завдяки ергономічній ручці та стильному дизайну він є одночасно зручним і практичним.'::text)) WHERE id = 50;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Boxed Blender — це потужний та компактний блендер, який ідеально підходить для приготування смузі, коктейлів та інших страв. Його зручний дизайн і багатофункціональність роблять цей пристрій незамінним помічником на вашій кухні.'::text)) WHERE id = 51;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сковорода вок із вуглецевої сталі — це універсальний кухонний інструмент, що підходить для смаження, пасерування та приготування у фритюрі. Міцна конструкція забезпечує рівномірний розподіл тепла для отримання ідеальних страв.'::text)) WHERE id = 52;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Обробна дошка — це незамінний кухонний аксесуар для приготування їжі. Виготовлена з міцного матеріалу, вона забезпечує безпечну та гігієнічну поверхню для нарізання та подрібнення продуктів.'::text)) WHERE id = 53;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Жовта соковитискач для цитрусових — це зручний інструмент для швидкого видобутку соку з цитрусових. Її яскравий колір додасть життєрадісного акценту вашому кухонному приладдю.'::text)) WHERE id = 54;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Яйцерізка — це зручне пристосування для акуратного нарізання варених яєць скибочками. Ідеально підходить для салатів, сендвічів та інших страв, де потрібна рівна нарізка.'::text)) WHERE id = 55;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Електрична плита — це портативне та ефективне рішення для приготування їжі. Ідеально підходить для невеликих кухонь або як додаткова варильна поверхня для різноманітних кулінарних завдань.'::text)) WHERE id = 56;
