    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Виделка — це класичний столовий прибор для щоденного використання та сервірування страв. Її довговічний та ергономічний дизайн робить її надійним вибором для кожної оселі.'::text)) WHERE id = 58;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Склянка — це універсальна та елегантна ємність для різноманітних напоїв. Прозорий дизайн дозволяє насолоджуватися кольором та текстурою вашого напою.'::text)) WHERE id = 59;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Чорна тертка — це зручний кухонний інструмент для натирання сиру, овочів та інших продуктів. Стильний дизайн та гострі леза роблять процес приготування швидким та легким.'::text)) WHERE id = 60;
