    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Форма для льоду — це практичний аксесуар для створення льоду різних форм. Ідеально підходить для охолодження напоїв та додавання креативного елемента до подачі страв.'::text)) WHERE id = 62;
