    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Ніж — це головний кухонний інструмент для нарізання, шинкування та подрібнення продуктів. Гостре лезо та ергономічна ручка роблять його надійним помічником у підготовці інгредієнтів.'::text)) WHERE id = 64;
