    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Спортивний мотоцикл розроблений для швидкості та маневреності, має стильний аеродинамічний профіль. Підійде райдерам, які прагнуть динамічного та драйвового досвіду водіння.'::text)) WHERE id = 117;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Мило для рук Attitude Super Leaves — це натуральний та живильний засіб, збагачений екстрактами суперлистя. Воно ефективно очищує та зволожує шкіру, залишаючи відчуття свіжості та м''якості.'::text)) WHERE id = 118;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Гель для душу Olay Ultra Moisture із маслом ши — це розкішний засіб, який зволожує та живить шкіру. Насолоджуйтесь багатою піною та шовковистою гладкістю вашої шкіри.'::text)) WHERE id = 119;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Лосьйон для обличчя та тіла Vaseline Men розроблений спеціально для тривалого зволоження чоловічої шкіри. Він швидко вбирається та допомагає зберегти шкіру здоровою та доглянутою.'::text)) WHERE id = 120;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('iPhone 5s — це класичний смартфон, відомий своїм компактним дизайном та передовими для свого часу функціями. Попри вік моделі, він досі забезпечує стабільну роботу.'::text)) WHERE id = 121;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('iPhone 6 — це стильний та функціональний смартфон зі збільшеним дисплеєм та покращеною продуктивністю. В свій час він задав нові стандарти дизайну та можливостей.'::text)) WHERE id = 122;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('iPhone 13 Pro — це інноваційний смартфон із потужною системою камер, високопродуктивним чіпом та приголомшливим дисплеєм. Ідеальний вибір для тих, хто вимагає найкращих технологій.'::text)) WHERE id = 123;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('iPhone X — флагманський смартфон із безрамковим OLED-дисплеєм, технологією розпізнавання обличчя Face ID та вражаючою продуктивністю. Це визначна віха в дизайні та інноваціях Apple.'::text)) WHERE id = 124;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Oppo A57 — це смартфон середнього класу, відомий своїм елегантним дизайном та збалансованими характеристиками. Завдяки поєднанню продуктивності та доступної ціни він став дуже популярним.'::text)) WHERE id = 125;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Oppo F19 Pro Plus — це багатофункціональний смартфон, орієнтований на можливості камери. Він може похвалитися передовими функціями для зйомки та високою продуктивністю, що забезпечує користувачеві преміальний досвід експлуатації.'::text)) WHERE id = 126;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Серія Oppo K1 пропонує лінійку смартфонів з різноманітними характеристиками та функціями. Смартфони Oppo K1 відомі своїм стильним дизайном і надійною роботою, задовольняючи найрізноманітніші потреби користувачів.'::text)) WHERE id = 127;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Realme C35 — це бюджетний смартфон, зосереджений на наданні основних функцій для повсякденного використання. Він пропонує стабільну продуктивність та зручний інтерфейс.'::text)) WHERE id = 128;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Realme X — це смартфон середнього цінового сегмента, відомий своїм елегантним дизайном та вражаючим дисплеєм. Він забезпечує чудовий баланс між продуктивністю та можливостями камери для користувачів, які шукають якісний пристрій.'::text)) WHERE id = 129;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Realme XT — це багатофункціональний смартфон з акцентом на технології камери. Він оснащений передовими сенсорами, що дозволяють створювати високоякісні фото та відео, стаючи ідеальним вибором для ентузіастів мобільної фотографії.'::text)) WHERE id = 130;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Samsung Galaxy S7 — це флагманський смартфон, відомий своїм витонченим дизайном та передовими характеристиками. Пристрій оснащено дисплеєм високої чіткості, потужною камерою та надійною продуктивністю.'::text)) WHERE id = 131;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Samsung Galaxy S8 — це преміальний смартфон із дисплеєм Infinity Display, який забезпечує неймовірні візуальні враження. Модель вирізняється просунутими можливостями камери та використанням найсучасніших технологій.'::text)) WHERE id = 132;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Samsung Galaxy S8 — це флагманський пристрій, оснащений динамічним AMOLED-дисплеєм, універсальною системою камер та високою потужністю. Цей смартфон уособлює собою інновації та досконалість у світі мобільних технологій.'::text)) WHERE id = 133;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Vivo S1 — це стильний смартфон середнього класу, що поєднує привабливий дизайн та відмінну продуктивність. Він оснащений яскравим дисплеєм, якісною камерою та надійним функціоналом.'::text)) WHERE id = 134;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Vivo V9 — це смартфон, відомий своїм елегантним дизайном з акцентом на якісні селфі. Він вирізняється безрамковим екраном із «чубчиком», подвійною камерою та сучасним зовнішнім виглядом.'::text)) WHERE id = 135;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Vivo X21 — це преміальний смартфон, орієнтований на інноваційні технології. Він має вбудований у дисплей сканер відбитків пальців, екран високої чіткості та передові можливості камери.'::text)) WHERE id = 136;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Американський футбол (м''яч) — це класичний м''яч для гри в американський футбол. Він спеціально розроблений для кидків та ловіння, будучи незамінним елементом екіпірування для цього виду спорту.'::text)) WHERE id = 137;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Бейсбольний м''яч — це стандартний м''яч для гри в бейсбол. Він має міцне шкіряне покриття та розроблений для подач, відбивання та ловіння під час гри.'::text)) WHERE id = 138;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Бейсбольна рукавиця — це захисний аксесуар для гравців у бейсбол. Вона створена для того, щоб комфортно ловити м''яч, забезпечуючи гравцеві максимальний контроль під час гри.'::text)) WHERE id = 139;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Баскетбольний м''яч — це стандартний м''яч для гри в баскетбол. Призначений для ведення, кидків та передач; підходить як для гри в залі, так і на відкритих майданчиках.'::text)) WHERE id = 140;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Баскетбольне кільце — це міцна конструкція з обруча та сітки, що кріпиться до баскетбольного щита. Воно слугує ціллю для влучань та нарахування очок у грі.'::text)) WHERE id = 141;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('М''яч для крикету — це твердий шкіряний м''яч, що використовується в грі в крикет. Його жорсткість та конструкція швів безпосередньо впливають на динаміку гри.'::text)) WHERE id = 142;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Бита для крикету — це ключовий інструмент для гри в крикет, яким бетсмени відбивають м''яч. Вона виготовляється з дерева та доступна у різних розмірах і дизайнах.'::text)) WHERE id = 143;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Шолом для крикету — це захисний головний убір, який носять гравці в крикет, особливо бетсмени та вікет-кіпери. Він забезпечує надійний захист від швидких подач та відскоків м''яча.'::text)) WHERE id = 144;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Вікет для крикету — це конструкція з трьох дерев''яних стовпчиків (стампів) та двох перекладин (бейлів). Бетсмени повинні захищати вікет, намагаючись заробити якомога більше очок (ранів).'::text)) WHERE id = 145;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Пір''яний волан — це аксесуар для бадмінтону. Виготовлений із натурального пір''я, він розроблений для високошвидкісної гри, забезпечуючи стабільність та точність польоту під час матчів.'::text)) WHERE id = 146;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Футбольний м''яч — це стандартний м''яч для гри у футбол. Він спеціально розроблений для професійного або аматорського ведення м''яча, пасів та ударів.'::text)) WHERE id = 147;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('М''яч для гольфу — це невеликий м''яч із характерними заглибленнями (димплами) на поверхні. Така конструкція забезпечує аеродинамічну підйомну силу та більшу дальність польоту при ударі ключкою.'::text)) WHERE id = 148;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Ключка для гольфу (айрон) — це тип ключки, призначений для виконання різних ударів. Вона має суцільнометалеву головку і використовується для підхідних ударів, чіпінгу та інших технічних прийомів.'::text)) WHERE id = 149;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Металева бейсбольна бита — це міцна та легка бита, виготовлена з металевих сплавів. Вона широко використовується в бейсболі як для офіційних ігор, так і для тренувань з відбивання.'::text)) WHERE id = 150;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Тенісний м''яч — це стандартний м''яч для гри у великий теніс. Він розроблений для оптимального відскоку та гри ракеткою під час матчів або тренувань.'::text)) WHERE id = 151;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Тенісна ракетка — це основний інвентар для гри у великий теніс. Вона складається з обідка з натягнутими струнами та зручної ручки, що дозволяє гравцям впевнено відбивати м''яч.'::text)) WHERE id = 152;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Волейбольний м''яч — це стандартний м''яч, призначений для гри у волейбол. Його конструкція ідеально підходить для передач, пасів та нападаючих ударів через сітку під час гри.'::text)) WHERE id = 153;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Чорні сонцезахисні окуляри — класичний та стильний вибір. Мають елегантну чорну оправу та тоновані лінзи, що забезпечують захист від ультрафіолету та створюють модний образ.'::text)) WHERE id = 154;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Класичні сонцезахисні окуляри вирізняються позачасовим дизайном з нейтральною оправою та лінзами із захистом від УФ-випромінювання. Це універсальний аксесуар для будь-якої ситуації.'::text)) WHERE id = 155;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Зелено-чорні окуляри вражають сміливим поєднанням кольорів, додаючи яскравий акцент вашій колекції аксесуарів. Вони виглядають стильно та привертають увагу.'::text)) WHERE id = 156;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Святкові окуляри створені, щоб додати родзинку вашому образу на вечірці. Завдяки унікальним формам та яскравим оправам вони стануть чудовим доповненням святкового настрою.'::text)) WHERE id = 157;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сонцезахисні окуляри класичного дизайну, де головний акцент зроблено на функціональності. Вони забезпечують надійний захист від сонця та мають лаконічний вигляд.'::text)) WHERE id = 158;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('iPad Mini 2021 у кольорі Starlight — це компактний та потужний планшет від Apple. Завдяки приголомшливому дисплею Retina, продуктивному процесору серії A та витонченому дизайну він пропонує можливості преміум-класу.'::text)) WHERE id = 159;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Samsung Galaxy Tab S8 Plus у сірому кольорі — це високопродуктивний Android-планшет. Великий AMOLED-дисплей, потужний процесор та підтримка стилуса S Pen роблять його ідеальним для роботи та розваг.'::text)) WHERE id = 160;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Samsung Galaxy Tab у білому кольорі — це стильний та багатофункціональний Android-планшет. Яскравий екран, тривалий час автономної роботи та широкий набір функцій забезпечують чудовий досвід користування.'::text)) WHERE id = 161;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Синя сукня — це чарівний та елегантний вибір для будь-якого випадку. Насичений колір та зручний крій додадуть витонченості вашому гардеробу.'::text)) WHERE id = 162;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Дитяча літня сукня — легка та повітряна модель, створена для спекотної погоди. Завдяки грайливим принтами та натуральним тканинам у ній буде комфортно та стильно протягом усього літа.'::text)) WHERE id = 163;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сіра сукня — це універсальний та стильний варіант на всі випадки життя. Нейтральний колір дозволяє поєднувати її як із повсякденним, так і з вечірнім взуттям, що робить її базовою річчю в гардеробі.'::text)) WHERE id = 164;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Коротка сукня — це грайлива та актуальна модель. Ідеально підходить для повсякденних прогулянок або святкових подій, поєднуючи в собі моду та комфорт.'::text)) WHERE id = 165;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сукня у клітинку (тартан) — це класика, яка привносить нотку вишуканості та традиційного шарму у ваш стиль. Ідеальний варіант для осінньо-зимового сезону.'::text)) WHERE id = 166;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('300 Touring — це стильний та комфортний седан, відомий своїми розкішними функціями та плавністю ходу.'::text)) WHERE id = 167;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Charger SXT RWD — потужний і спортивний задньопривідний седан, що пропонує ідеальний баланс динаміки та практичності.'::text)) WHERE id = 168;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Dodge Hornet GT Plus — компактний і маневровий хетчбек, який ідеально підходить для міської їзди, додаючи драйву вашому стилю життя.'::text)) WHERE id = 169;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Durango SXT RWD — місткий та універсальний позашляховик (SUV), що цінується за потужність та зручність для всієї родини.'::text)) WHERE id = 170;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Pacifica Touring — стильний і добре оснащений мінівен, який гарантує комфорт і зручність під час сімейних подорожей.'::text)) WHERE id = 171;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Синя жіноча сумка — це стильний та місткий аксесуар для щоденного використання. Насичений колір і наявність кількох відділень роблять її не лише модною, а й функціональною.'::text)) WHERE id = 172;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Шкіряна жіноча сумка Heshe — це втілення розкоші та високої якості для витончених жінок. Позачасовий дизайн і довговічність роблять її незамінним аксесуаром.'::text)) WHERE id = 173;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Жіноча сумка Prada — це культовий дизайнерський аксесуар, який випромінює елегантність та статусність. Виконана з особливою точністю, вона стане головним акцентом образу справжньої модниці.'::text)) WHERE id = 174;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Білий рюкзак зі штучної шкіри — трендовий та практичний аксесуар для сучасної жінки. Елегантний дизайн і достатньо місця для речей роблять його ідеальним як для повсякденного стилю, так і для активного способу життя.'::text)) WHERE id = 175;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Жіноча чорна сумка — це класичний та універсальний аксесуар, що вдало доповнить будь-який образ. Завдяки вічному чорному кольору та функціональному дизайну, вона стане незамінним елементом гардероба кожної жінки.'::text)) WHERE id = 176;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Чорна вечірня сукня — це втілення елегантності та позачасового стилю. Лаконічний чорний дизайн робить її ідеальним вибором для офіційних заходів та урочистих подій, підкреслюючи ваш вишуканий смак.'::text)) WHERE id = 177;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Шкіряний корсет зі спідницею — це сміливий та зухвалий ансамбль, що поєднує стильний корсет із гармонійно підібраною спідницею. Ідеально підходить для тих, хто прагне виділитися та зробити ефектний акцент на будь-якій події.'::text)) WHERE id = 178;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Корсет із чорною спідницею — це стильний та універсальний комплект, що поєднує модний корсет із класичною спідницею. Цей образ виглядає сучасно та гармонійно, підходячи для різних випадків.'::text)) WHERE id = 179;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сукня в горошок — це стильне та зручне вбрання з класичним принтом. Ідеально підходить для повсякденних виходів, додаючи вашому образу нотку легкості та грайливості.'::text)) WHERE id = 180;
