    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сережки із зеленим кристалом — це сліпучий аксесуар, головною окрасою якого є яскравий камінь. Завдяки класичному дизайну вони додадуть нотку розкоші вашому вбранню, що ідеально підходить для урочистих подій.'::text)) WHERE id = 182;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сережки з овальним зеленим каменем — це стильний та універсальний аксесуар унікальної форми. Завдяки насиченому кольору та сучасному дизайну вони стануть яскравим акцентом вашого образу як у повсякденні, так і на свята.'::text)) WHERE id = 183;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Сережки «Тропіки» — це яскравий та грайливий аксесуар, натхненний тропічними мотивами. Насичені кольори та живий дизайн ідеально підійдуть для того, щоб додати нотку літнього настрою вашому стилю.'::text)) WHERE id = 184;
