    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Годинник Rolex Cellini Moonphase — це справжній шедевр годинникового мистецтва. З функцією індикації фаз Місяця, він демонструє виняткову майстерність та елегантність, якими славиться бренд Rolex.'::text)) WHERE id = 191;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Жіночий годинник Rolex Datejust — це культова модель, створена для сучасних жінок. Поєднання позачасового дизайну та функції відображення дати забезпечує як естетичну насолоду, так і високу функціональність.'::text)) WHERE id = 192;
    UPDATE products SET attributes = jsonb_set(COALESCE(attributes, '{}'::jsonb), '{description_uk}', to_jsonb('Золотий жіночий годинник — це приголомшливий аксесуар, що поєднує в собі розкіш і стиль. Завдяки позолоченому корпусу та витонченому дизайну, він стане ідеальним доповненням до будь-якого образу.'::text)) WHERE id = 193;
